function connectDecky(name) {
  const connector = window.__DECKY_SECRET_INTERNALS_DO_NOT_USE_OR_YOU_WILL_BE_FIRED_deckyLoaderAPIInit;
  if (!connector) throw new Error('Decky Loader API is unavailable. Update Decky Loader and reload the plugin.');
  let api;
  try { api = connector.connect(2, name); }
  catch { api = connector.connect(1, name); }
  return api;
}

/* Steam integration: reads and writes through Steam's live API, never edits localconfig.vdf. */
function waitDetails(apps, appid, predicate = () => true, timeout = 8000) {
  return new Promise((resolve, reject) => {
    if (!apps?.RegisterForAppDetails) { reject(new Error('Steam app-details API is unavailable. No launch options were changed.')); return; }
    let registration, done = false;
    const timer = setTimeout(() => finish(new Error('Steam did not return the expected launch options. Retry reading launch options; no guessed value is used.')), timeout);
    function finish(error, value) {
      if (done) return;
      done = true; clearTimeout(timer);
      try { registration?.unregister?.(); } catch { /* Listener cleanup must not corrupt a completed write. */ }
      error ? reject(error) : resolve(value);
    }
    try {
      registration = apps.RegisterForAppDetails(Number(appid), details => {
        if (typeof details?.strLaunchOptions === 'string' && predicate(details.strLaunchOptions)) finish(null, details.strLaunchOptions);
      });
      if (done) registration?.unregister?.(); // Handles a synchronous initial callback.
    } catch (e) { finish(e); }
  });
}
async function readLaunch(apps, appid) { return waitDetails(apps, appid); }
async function writeLaunch(apps, appid, value) {
  if (!apps?.SetAppLaunchOptions) throw new Error('Steam launch-option setter is unavailable. Game changes must be recovered, not reported as applied.');
  const before = await readLaunch(apps, appid);
  if (before === value) return before;
  // Subscribe before writing, to avoid missing the update notification.
  const verified = waitDetails(apps, appid, candidate => candidate === value);
  try { apps.SetAppLaunchOptions(Number(appid), value); }
  catch (error) { verified.catch(() => {}); throw error; }
  return await verified;
}

async function commitIntegration({ apps, appid, draft, observed, launch, remove, approval, forceRepair=false, rpc, job, onStatus = () => {} }) {
  const before = await readLaunch(apps, appid);
  if (before !== observed) throw new Error('Steam launch options changed since they were loaded. Reload them before applying; the new value was not overwritten.');
  const prepared = await job('prepare', {profile:draft, launch, launch_actual:before, remove, approval, force_repair:forceRepair});
  let written = false;
  try {
    const current = await readLaunch(apps, appid);
    if (current !== before) throw new Error('Steam launch options changed during file preparation. The file transaction will be rolled back.');
    onStatus('Writing and verifying Steam launch options');
    const verified = await writeLaunch(apps, appid, prepared.launch_after);
    written = true;
    const result = await rpc('finish', {appid, token:prepared.token, verified});
    return {...result, launch:verified};
  } catch (error) {
    onStatus('Verifying recovery state');
    try {
      const diagnostic = await rpc('diagnostics', {appid});
      const current = await readLaunch(apps, appid);
      // A response may be lost after the backend committed successfully.
      if (!diagnostic.pending && diagnostic.manifest?.installed_launch === prepared.launch_after && current === prepared.launch_after) {
        return {committed:true, launch:current, recovered_response:true};
      }
      if (!diagnostic.pending) throw new Error('No pending journal is available; inspect diagnostics before making more changes.');
      if (current === prepared.launch_after && current !== before) await writeLaunch(apps, appid, before);
      else if (current !== before && written) throw new Error('Launch options were edited independently after the write. Recovery is required.');
      await rpc('rollback', {appid, token:prepared.token});
    } catch (recoveryError) {
      throw new Error(`${error.message || error}\nRecovery is required in Apply: ${recoveryError.message || recoveryError}`);
    }
    throw new Error(`${error.message || error}\nFile changes were rolled back.`);
  }
}

