function customEntries(value){
  const result=Object.create(null);
  for(const group of String(value||'').split(';')){
    const split=group.indexOf('=');if(split<0)continue;
    for(const raw of group.slice(0,split).split(',')){
      const name=raw.trim().toLowerCase().replace(/\.dll$/,'');
      if(name)result[name]=group.slice(split+1).trim();
    }
  }
  return result;
}
function serializeOverrides(entries){return Object.entries(entries).map(([name,order])=>`${name}=${order}`).join(';');}
function moduleNames(value){
  const names=String(value||'').split(',').map(x=>x.trim().toLowerCase().replace(/\.dll$/,''));
  if(!names.length||names.some(x=>!/^\*?[a-z0-9_][a-z0-9_.+-]{0,127}$/.test(x)||x.includes('..')))
    throw new Error('Enter comma-separated DLL basenames such as dxgi, version, winmm. No paths, empty entries or shell commands.');
  return [...new Set(names)];
}
function mergeCustomModules(value,names,order,keepExisting=false){
  const entries=customEntries(value);
  for(const name of names)if(!keepExisting||!Object.hasOwn(entries,name))entries[name]=order;
  return serializeOverrides(entries);
}
