   if(doc.visibilityState!=='hidden'&&(!doc.hasFocus||doc.hasFocus())&&el.isConnected&&(scope?.contains(doc.activeElement)||doc.activeElement===doc.body)&&y){el.scrollTop+=y*dt*.65;}
