    // the operation even if it started after this review was displayed.
    let fresh=await job('plan',{profile:draft,launch:target,remove:false,force_repair:force});
    if(fresh.approval_token!==approvedPlan.approval_token||fresh.blockers?.length){await prepareGuidedReview({force});status('The installation plan changed. Check this review before applying.');return;}
    const installedRuntimes=await installGuidedRuntimes(draft,current);
    fresh=await job('plan',{profile:draft,launch:target,remove:false,force_repair:force});
    if(fresh.blockers?.length||(fresh.approval_token!==approvedPlan.approval_token&&!(installedRuntimes&&sameGuidedGraphicsPlan(approvedPlan,fresh)))){setReview(fresh);status('The graphics plan changed. Check this review before applying.');return;}
